/* =====================================================================
   FORM-14 · FACTURA DE REPARACIÓN  (ficha «f5» de Taller, entre FORM-02 y FORM-03)
   Se rellena sola desde el presupuesto y los datos de recepción; el gerente o recepción la
   revisan y la emiten. Emitida queda bloqueada; si hay que corregir, el gerente la reabre con
   motivo y la nueva emisión sale como rectificativa (-R1, -R2…). El mecánico no ve importes.
   Este módulo solo AÑADE: engancha con las funciones de taller.js (tCabecera, tRenderBody, etc.).
   ===================================================================== */
const FC_EMISOR={razon:"MAYLIN Y YERAY S.L.",nif:"B93975647",direccion:"CALLE VALLE LARGO 8",cp:"35610 - Polígono Industrial Costa de Antigua",telefono:"643 56 60 98",email:"volcanocars2026@gmail.com"};
const FC_TIPOS={MO:"Mano de obra",REC:"Recambio",OTRO:"Otro"};
const fcE=n=>Number(n||0).toLocaleString("es-ES",{minimumFractionDigits:2,maximumFractionDigits:2,useGrouping:"always"})+" €";
const fcR2=n=>Math.round((n+Number.EPSILON)*100)/100;
const fcVe=()=>ES_GER()||(ME&&ME.rol==="recepcion");
function fcTotales(x){
  const imp=(x.lineas||[]).map(l=>fcR2(tNum(l.cant)*tNum(l.precio)*(1-Math.min(100,tNum(l.dto))/100)));
  const suma=fcR2(imp.reduce((a,b)=>a+b,0)), dto=Math.min(suma,fcR2(tNum(x.descuentoGlobal))), base=fcR2(suma-dto);
  const pct=x.igicTipo==="7"?7:x.igicTipo==="otro"?tNum(x.igicOtro):0, igic=Math.round(base*pct)/100;
  return {imp,suma,dto,base,pct,igic,total:fcR2(base+igic)};
}
function fcNueva(){ // borrador: presupuesto + recepción; solo se guarda si el usuario lo edita
  if(typeof TF==="undefined"||!TF||!TF.orden) return null;
  const o=TF.orden, f=TF.fichas, f1=f.f1||{}, c=f1.cliente||{}, v=f1.vehiculo||{}, p=o.presupuesto;
  if(f.f5&&f.f5.lineas) return tClone(f.f5);
  const ig=p?Number(p.igic):7;
  return {fechaOperacion:"",
    cliente:{nombre:c.nombre||o.cliente.nombre||"",doc:c.doc||"",direccion:"",cp:"",telefono:c.telefono||o.cliente.telefono||"",email:c.email||o.cliente.email||""},
    vehiculo:{matricula:v.matricula||o.vehiculo.matricula||"",vin:v.vin||"",marcaModelo:v.marcaModelo||o.vehiculo.coche||"",kmEntrada:String(v.km||o.vehiculo.km||"").replace(/\D/g,""),kmSalida:""},
    lineas:p&&p.lineas?p.lineas.map(l=>({tipo:"OTRO",ref:"",desc:String(l.c||""),cant:l.n,precio:l.p,dto:0})):[],
    descuentoGlobal:0,igicTipo:ig===7?"7":ig===0?"0":p?"otro":"7",igicOtro:ig&&ig!==7?ig:0,observaciones:"",cerrada:false,rect:0,emision:null};
}
function fcTab(){ return fcVe()?[["f5","FORM-14","Factura"]]:[]; }
function fcEstado(){ const x=TF.fichas.f5; if(!x||x.lineas===undefined) return ["","Sin empezar"]; return x.cerrada?["ok","Emitida"]:["curso","Borrador"]; }
function fcEditable(){ const x=TF.fichas.f5; return fcVe()&&!(x&&x.cerrada); }
const fcI=(l,p,{cls="",tipo="text",ph="",m=""}={})=>{ const v=tGet(TW.f5,p); return `<div class="field ${cls}"><label>${l}</label><input class="in" type="${tipo}" ${m?`inputmode="${m}"`:""} data-fc="${p}" value="${tEsc(v)}" placeholder="${esc(ph)}" ${fcEditable()?"":"disabled"}></div>`; };
function fcLinea(l,i){ const d=fcEditable()?"":"disabled", t=fcTotales(TW.f5).imp[i]||0;
  return `<div class="fc-l" data-fcl="${i}">
   <div class="field fc-d"><label>Descripción</label><input class="in" data-fcl="${i}.desc" value="${tEsc(l.desc)}" placeholder="Ej.: Cambio de aceite y filtros" ${d}></div>
   <div class="field"><label>Tipo</label><select class="in" data-fcl="${i}.tipo" ${d}>${Object.entries(FC_TIPOS).map(([k,n])=>`<option value="${k}" ${l.tipo===k?"selected":""}>${n}</option>`).join("")}</select></div>
   <div class="field"><label>Ref.</label><input class="in" data-fcl="${i}.ref" value="${tEsc(l.ref)}" ${d}></div>
   <div class="field"><label>Cant.</label><input class="in num" inputmode="decimal" data-fcl="${i}.cant" value="${tEsc(l.cant)}" ${d}></div>
   <div class="field"><label>Precio €</label><input class="in num" inputmode="decimal" data-fcl="${i}.precio" value="${tEsc(l.precio)}" ${d}></div>
   <div class="field"><label>Dto. %</label><input class="in num" inputmode="decimal" data-fcl="${i}.dto" value="${tEsc(l.dto||"")}" ${d}></div>
   <div class="fc-im"><small>Importe</small><b data-fcimp="${i}">${fcE(t)}</b></div>
   ${fcEditable()?`<button type="button" class="btn b-ghost b-sm fc-x" data-fcdel="${i}" aria-label="Quitar línea">✕</button>`:""}</div>`; }
function fcTotHTML(){ const t=fcTotales(TW.f5);
  return `<div class="fc-r"><span>Suma de líneas</span><b>${fcE(t.suma)}</b></div>${t.dto?`<div class="fc-r"><span>Descuento</span><b>−${fcE(t.dto)}</b></div>`:""}<div class="fc-r"><span>Base imponible</span><b>${fcE(t.base)}</b></div><div class="fc-r"><span>IGIC ${String(t.pct).replace(".",",")} %</span><b>${fcE(t.igic)}</b></div><div class="fc-r fc-t"><span>TOTAL</span><b>${fcE(t.total)}</b></div>`; }
function fcRender(){
  if(!fcVe()) return `<div class="t-lock"><span>🔒</span><div><b>La factura la prepara el gerente o recepción</b><small>Los importes no se muestran al equipo del taller.</small></div></div>`;
  if(!TW.f5) TW.f5=fcNueva();
  const x=TW.f5, f=TF.fichas.f5, ed=fcEditable(), em=f&&f.emision;
  const serie=(f&&f.rect)?"R":"F", anio=(new Date().getFullYear());
  const pre=TF.orden.presupuesto&&TF.orden.presupuesto.lineas&&TF.orden.presupuesto.lineas.length;
  return `${f&&f.cerrada?tBloqueado("f5","Factura emitida · nº "+esc(em?em.numero:"")+(em?" · "+esc(tFH(em.t))+" · huella "+esc((em.huella||"").slice(0,10))+"…":"")):`<div class="t-info fc-info"><b>${f&&f.rect?"Factura rectificativa":"Factura"}</b> <span>El número (serie ${serie}-${anio}-NNNN, correlativo) se asigna al pulsar «Emitir»${f&&f.rect&&f.origen?" y rectificará a la "+esc(f.origen):""}. ${pre?"Cargada desde el presupuesto: revísala antes de emitir.":"Esta orden no tiene presupuesto: añade las líneas."} Los datos del cliente y del coche vienen de la recepción.</span></div>`}
  <div id="tf-faltan" class="t-faltan" hidden></div>
  ${tSec(1,"Emisor","Datos fijos de la empresa",`<div class="fc-em"><b>${FC_EMISOR.razon}</b><span>NIF ${FC_EMISOR.nif} · ${FC_EMISOR.direccion}, ${FC_EMISOR.cp}</span><span>${FC_EMISOR.email}</span></div>`)}
  ${tSec(2,"Cliente","",`<div class="t-g2">${fcI("Nombre o empresa *","cliente.nombre")}${fcI("DNI / NIE / CIF","cliente.doc")}${fcI("Dirección","cliente.direccion")}${fcI("C.P. y población","cliente.cp")}${fcI("Teléfono","cliente.telefono",{tipo:"tel"})}${fcI("Email","cliente.email",{tipo:"email"})}</div>`)}
  ${tSec(3,"Vehículo","",`<div class="t-g2">${fcI("Matrícula *","vehiculo.matricula")}${fcI("Marca y modelo","vehiculo.marcaModelo")}${fcI("VIN","vehiculo.vin")}${fcI("Km entrada","vehiculo.kmEntrada",{m:"numeric"})}${fcI("Km salida","vehiculo.kmSalida",{m:"numeric"})}${fcI("Fecha de la operación","fechaOperacion",{tipo:"date"})}</div>`)}
  ${tSec(4,"Detalle de la reparación","Mano de obra, recambios y otros",`<div id="fc-lineas">${x.lineas.map(fcLinea).join("")||'<p class="hint">Sin líneas todavía.</p>'}</div>${ed?`<div class="fc-acc"><button type="button" class="btn b-ghost b-sm" data-fcadd="MO">+ Mano de obra</button><button type="button" class="btn b-ghost b-sm" data-fcadd="REC">+ Recambio</button><button type="button" class="btn b-ghost b-sm" data-fcadd="OTRO">+ Otro</button>${pre?`<button type="button" class="btn b-ghost b-sm" data-fcpre>Recargar desde el presupuesto</button>`:""}</div>`:""}`)}
  ${tSec(5,"Totales","IGIC (Canarias)",`<div class="t-g2">${fcI("Descuento global (€)","descuentoGlobal",{m:"decimal"})}<div class="field"><label>Tipo de IGIC *</label><div class="t-seg" role="group">${[["7","7 % general"],["0","0 % exento"],["otro","Otro"]].map(([k,n])=>`<button type="button" data-fcigic="${k}" aria-pressed="${x.igicTipo===k}" ${ed?"":"disabled"}>${n}</button>`).join("")}</div></div>${x.igicTipo==="otro"?fcI("IGIC %","igicOtro",{m:"decimal"}):""}</div><div class="fc-tot" id="fc-tot">${fcTotHTML()}</div>`)}
  ${tSec(6,"Observaciones","Garantía, forma de pago…",`<div class="field"><textarea class="in" rows="3" data-fc="observaciones" ${ed?"":"disabled"}>${tEsc(x.observaciones)}</textarea></div>`)}
  ${tSec(7,"Libro de facturas","Para tu gestoría: todas las emitidas",`<div class="t-g2"><div class="field"><label>Desde</label><input class="in" type="date" id="fc-d"></div><div class="field"><label>Hasta</label><input class="in" type="date" id="fc-h"></div></div><div class="fc-acc"><button type="button" class="btn b-brand b-sm" data-fclib="csv">Descargar listado (Excel)</button><button type="button" class="btn b-ghost b-sm" data-fclib="ver">Comprobar integridad</button></div><div id="fc-lib" class="hint" aria-live="polite"></div>`)}`;
}
$("#tf").addEventListener("click",async e=>{ const b=e.target.closest("[data-fclib]"); if(!b||TF_TAB!=="f5") return; const out=$("#fc-lib"), q=$("#fc-d").value?("desde="+$("#fc-d").value+($("#fc-h").value?"&hasta="+$("#fc-h").value:"")):($("#fc-h").value?"hasta="+$("#fc-h").value:"");
  try{
    if(b.dataset.fclib==="ver"){ const r=await tApi("facturas/verificar"); out.innerHTML=r.ok?`<b style="color:#2f7d4f">✔ Todo correcto</b>: ${r.registros} factura${r.registros===1?"":"s"} registrada${r.registros===1?"":"s"}${r.ultima?", la última "+esc(r.ultima):""}. Cadena, huellas y numeración cuadran.`:`<b style="color:#b3261e">Hay problemas:</b><ul>${r.fallos.map(z=>`<li>${esc(z)}</li>`).join("")}</ul>`; }
    else { const r=await fetch("/api/taller/facturas/csv"+(q?"?"+q:""),{headers:{authorization:"Bearer "+PW}}); if(!r.ok) throw new Error((await r.json().catch(()=>({}))).error||"No se pudo preparar el listado"); const a=document.createElement("a"); a.href=URL.createObjectURL(await r.blob()); a.download="facturas-volcano-cars.csv"; document.body.appendChild(a); a.click(); a.remove(); out.textContent="Listado descargado (se abre con Excel)."; }
  }catch(err){ out.textContent=err.message; } });
function fcRefrescar(){ const t=fcTotales(TW.f5); const e=$("#fc-tot"); if(e) e.innerHTML=fcTotHTML(); t.imp.forEach((v,i)=>{ const b=document.querySelector(`[data-fcimp="${i}"]`); if(b) b.textContent=fcE(v); }); }
$("#tf").addEventListener("input",e=>{ const t=e.target; if(TF_TAB!=="f5"||!TW.f5||!fcEditable()) return;
  if(t.dataset.fc){ tSet(TW.f5,t.dataset.fc,t.value); tMarcar(); fcRefrescar(); }
  else if(t.dataset.fcl){ const [i,k]=t.dataset.fcl.split("."); if(TW.f5.lineas[+i]){ TW.f5.lineas[+i][k]=t.value; tMarcar(); fcRefrescar(); } } });
$("#tf").addEventListener("change",e=>{ const t=e.target; if(TF_TAB==="f5"&&t.matches("select[data-fcl]")&&TW.f5&&fcEditable()){ const [i,k]=t.dataset.fcl.split("."); TW.f5.lineas[+i][k]=t.value; tMarcar(); } });
$("#tf").addEventListener("click",e=>{ if(TF_TAB!=="f5"||!TW.f5||!fcEditable()) return; const q=s=>e.target.closest(s);
  const a=q("[data-fcadd]"); if(a){ TW.f5.lineas.push({tipo:a.dataset.fcadd,ref:"",desc:"",cant:1,precio:"",dto:""}); tMarcar(); tRenderBody(true); const l=document.querySelectorAll("#fc-lineas .fc-d input"); if(l.length) l[l.length-1].focus({preventScroll:true}); return; }
  const d=q("[data-fcdel]"); if(d){ TW.f5.lineas.splice(+d.dataset.fcdel,1); tMarcar(); tRenderBody(true); return; }
  const g=q("[data-fcigic]"); if(g){ TW.f5.igicTipo=g.dataset.fcigic; tMarcar(); tRenderBody(true); return; }
  if(q("[data-fcpre]")){ if(TW.f5.lineas.length&&!confirm("¿Sustituir las líneas actuales por las del presupuesto?")) return; const p=TF.orden.presupuesto; TW.f5.lineas=(p.lineas||[]).map(l=>({tipo:"OTRO",ref:"",desc:String(l.c||""),cant:l.n,precio:l.p,dto:0})); tMarcar(); tRenderBody(true); return; } });
/* ---------- impresión (A4): réplica del FORM-03 «Factura de reparación» del Manual SOP-01 ---------- */
const FC_LOGO="data:image/png;base64,";
function fcPagina(){ const x=TF.fichas.f5&&TF.fichas.f5.lineas?TF.fichas.f5:TW.f5; if(!x||!x.lineas) return '<article class="tp-pag fc-pag"><p class="tp-vacio">Factura sin preparar.</p></article>';
  const t=fcTotales(x), em=x.emision, c=x.cliente, v=x.vehiculo, E=FC_EMISOR, num=em?em.numero:"(sin emitir)";
  const P=(a,va,b,vb,cls="")=>`<tr class="${cls}"><th>${a}</th><td>${va==null?"":va}</td><th>${b}</th><td>${vb==null?"":vb}</td></tr>`;
  const bar=(n,t,s="")=>`<div class="fp-bar"><i>${n}</i><b>${t}</b>${s?`<small>${s}</small>`:""}</div>`;
  const n=Math.max(10,x.lineas.length), fila=i=>{ const l=x.lineas[i]; return l?`<tr><td>${esc(l.tipo==="OTRO"?"":l.tipo)}</td><td>${esc(l.ref)}</td><td>${esc(l.desc)}</td><td class="r">${esc(String(l.cant).replace(".",","))}</td><td class="r">${fcE(tNum(l.precio))}</td><td class="r">${l.dto?esc(String(l.dto).replace(".",","))+" %":""}</td><td class="r">${fcE(t.imp[i])}</td></tr>`:"<tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>"; };
  const ck=k=>`<span class="fp-ck">${x.igicTipo===k?"✕":""}</span>`;
  return `<article class="tp-pag fc-pag">
  <header class="fp-h"><img src="${FC_LOGO}" alt="Volcano Cars"><div><h1>${x.rect?"FACTURA RECTIFICATIVA":(x.cliente&&x.cliente.doc?"FACTURA DE REPARACIÓN":"FACTURA SIMPLIFICADA")}</h1><p>Documento de cobro al cliente</p><span class="fp-pill">FORM-14</span></div></header>${x.rect&&x.origen?`<p class="fp-rect">Rectifica a la factura <b>${esc(x.origen)}</b>${x.motivoRect?" · Motivo: "+esc(x.motivoRect):""}</p>`:""}
  <table class="fp-num"><tbody><tr><th>Nº de factura</th><td><b>${esc(num)}</b></td><th>Fecha emisión</th><td>${esc(tF(em?em.fecha:""))}</td><th>Fecha operación</th><td>${esc(tF(x.fechaOperacion||(em?em.fecha:"")))}</td></tr></tbody></table>
  <p class="fp-nota"><b>El nº de factura es correlativo (F-AAAA-NNNN) y no se repite.</b> Un error no se tacha: se emite factura rectificativa.</p>
  ${bar(1,"Datos del emisor","quien factura")}<table class="fp-t"><tbody>${P("Razón social",E.razon,"NIF / CIF",E.nif)}${P("Dirección",E.direccion,"CP / localidad",E.cp)}${P("Teléfono",E.telefono,"Correo electrónico",E.email)}</tbody></table>
  ${bar(2,"Datos del cliente")}<table class="fp-t"><tbody>${P("Nombre / empresa",esc(c.nombre),"DNI / NIE / CIF",esc(c.doc))}${P("Dirección",esc(c.direccion),"CP / localidad",esc(c.cp))}${P("Teléfono",esc(c.telefono),"Correo electrónico",esc(c.email))}</tbody></table>
  ${bar(3,"Datos del vehículo")}<table class="fp-t"><tbody>${P("Matrícula","<b>"+esc(v.matricula)+"</b>","Marca / modelo",esc(v.marcaModelo))}${P("Bastidor (VIN)",esc(v.vin),"Kilometraje",`<span class="fp-km"><em>entrada</em> ${esc(v.kmEntrada)} <em>km</em></span><span class="fp-km"><em>salida</em> ${esc(v.kmSalida)} <em>km</em></span>`)}</tbody></table>
  ${bar(4,"Detalle de la reparación","una línea por concepto · MO = mano de obra (horas de FORM-03 × tarifa) · REC = recambio")}
  <table class="fp-d"><thead><tr><th>Tipo</th><th>Referencia</th><th>Descripción</th><th class="r">Cant.</th><th class="r">Precio ud.</th><th class="r">Dto. %</th><th class="r">Importe €</th></tr></thead><tbody>${Array.from({length:n},(_,i)=>fila(i)).join("")}</tbody></table>
  <div class="fp-bar fp-sal"><i>5</i><b>Totales e IGIC</b></div>
  <p class="fp-for"><b>Base imponible</b> = suma de líneas − descuento global &nbsp;·&nbsp; <b>IGIC</b> = base × tipo &nbsp;·&nbsp; <b>Total</b> = base + IGIC</p>
  <div class="fp-fin"><div class="fp-izq"><div class="fp-ig"><b>Tipo de IGIC</b><span>${ck("7")} 7 % general</span><span>${ck("0")} 0 % exento</span><span>${ck("otro")} otro <u>${x.igicTipo==="otro"?esc(String(x.igicOtro).replace(".",",")):"&nbsp;&nbsp;&nbsp;&nbsp;"}</u> %</span></div><div class="fp-ob"><b>Observaciones</b><p>${esc(x.observaciones)}</p></div></div>
  <table class="fp-tot"><tbody><tr><th>Suma de líneas</th><td>${fcE(t.suma)}</td></tr><tr><th>Descuento global</th><td>${fcE(t.dto)}</td></tr><tr><th>Base imponible</th><td>${fcE(t.base)}</td></tr><tr><th>IGIC (tipo ${String(t.pct).replace(".",",")} %)</th><td>${fcE(t.igic)}</td></tr><tr class="fp-tt"><th>TOTAL FACTURA</th><td>${fcE(t.total)}</td></tr></tbody></table></div>
  ${em?"":'<p class="fp-borr">BORRADOR · sin validez hasta que se emita</p>'}
  <footer class="fp-pie"><span><b>Volcano Cars</b> · Sistema 01 · Taller, de la recepción a la entrega · FORM-14</span><span>Factura de reparación</span></footer></article>`; }
